"""Editable vector teaching diagrams. Each named group has a single visible role."""
from html import escape as e

def wrap(body,label,cls=''):
 return f'<svg class="drawing {cls}" data-illustration="{cls}" width="640" height="420" viewBox="0 0 640 420" role="img" aria-label="{e(label)}" xmlns="http://www.w3.org/2000/svg"><title>{e(label)}</title>{body}</svg>'

def glasses():
 # Front view: wearer's left lens is at viewer's right.
 return wrap('''<g class="glasses-world"><g class="frame-parts" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"><path d="M61 173L42 165 24 169M579 173L598 165 616 169"/><path d="M270 177Q320 151 370 177"/><rect class="lens-shape right-lens" x="62" y="128" width="208" height="143" rx="55"/><rect class="lens-shape left-lens" x="370" y="128" width="208" height="143" rx="55"/><path d="M62 155L128 214M578 155L512 214" opacity=".4"/></g><rect class="lens-tint" x="373" y="131" width="202" height="137" rx="18"/><g class="lens-heart"><path d="M512 228C479 208 495 190 512 204C529 190 545 208 512 228Z"/></g><g class="lens-star"><path d="M512 195L517 207 531 208 520 217 523 231 512 224 501 231 504 217 493 208 507 207Z"/></g><g class="lens-selection" fill="none" stroke="var(--accent)" stroke-width="1.5"><rect x="354" y="112" width="240" height="175" rx="4"/><path d="M354 124V112H366M582 112H594V124M594 275V287H582M366 287H354V275" stroke-width="5"/></g><g class="sun-rays" fill="none" stroke="var(--gold)" stroke-width="2"><circle cx="570" cy="50" r="16"/><path d="M570 22V12M570 78V88M542 50H532M598 50H608M550 30L542 22M590 70L598 78M590 30L598 22M550 70L542 78M570 98L545 128M530 88L512 128"/></g></g>''','사각 안경의 형태와 프레임 재질, 착용자 기준 왼쪽 렌즈의 작은 표시','glasses')

def shop():
 rain=''.join(f'<path d="M{x} {y}l-9 23"/>' for y in [48,112,182,245] for x in range(40,621,58))
 return wrap(f'''<rect class="night-sky" x="12" y="12" width="616" height="396" rx="10"/><g class="moon"><circle cx="539" cy="73" r="22" fill="var(--paper)"/><circle cx="549" cy="66" r="22" fill="var(--night)"/></g><path class="road" d="M12 290H628V408H12Z"/><g class="store" stroke="var(--ink)" stroke-width="3" stroke-linejoin="round"><path fill="var(--paper)" d="M159 149H481V301H159Z"/><path fill="var(--ink)" d="M148 140H492V154H148Z"/><path class="store-sign" d="M159 160H481V192H159Z"/><path fill="var(--bone)" d="M179 208H289V277H179Z"/><path fill="var(--bone)" d="M311 207H454V298H311Z"/><path d="M382 207V298M317 251H377" fill="none"/><circle cx="371" cy="251" r="3" fill="var(--ink)"/></g><g class="rain" stroke="var(--rain)" stroke-width="2" fill="none">{rain}</g><g class="reflection" stroke="var(--accent)" stroke-linecap="round"><path d="M165 324H475" stroke-width="10"/><path d="M190 345H450" stroke-width="7"/><path d="M159 365H480" stroke-width="4"/><path d="M214 385H426" stroke-width="2"/></g><g class="props" fill="none" stroke="var(--ink)" stroke-width="3"><path d="M93 301V249M83 270Q65 239 93 243Q121 240 105 269M517 299H551V275H517ZM525 275V255H543V275"/></g>''','편의점, 밤, 비, 젖은 도로와 간판 불빛의 반사를 단계별로 연결한 장면','shop')

def street():
 return wrap('''<rect class="night-sky" x="12" y="12" width="616" height="396" rx="10"/><path class="road" d="M224 205H416L603 408H37Z"/><g fill="var(--paper)" stroke="var(--ink)" stroke-width="2"><path d="M50 115H180V304H50ZM458 79H590V305H458ZM199 67H254V221H199ZM390 106H434V237H390Z"/></g><g class="lamps" stroke="var(--ink)" stroke-width="3" fill="none"><path d="M160 323V163Q160 145 186 145M480 323V163Q480 145 454 145"/></g><g class="light-cones"><path d="M186 145L153 323H251ZM454 145L389 323H487Z"/></g><g class="person" fill="var(--ink)"><circle cx="320" cy="258" r="11"/><path d="M309 274H331L338 315H327V342H313V315H302Z"/></g>''','시간, 사람의 유무, 빛의 색으로 달라지는 거리의 도식','street')

def room():
 return wrap('''<g fill="none" stroke="var(--line)" stroke-width="2"><path d="M72 52H567V332H72ZM72 332L12 408M567 332L628 408M12 408H628M128 102H244V219H128ZM186 102V219M128 160H244"/></g><g class="room-anchor"><rect x="280" y="165" width="125" height="83" rx="6" fill="var(--paper)" stroke="var(--ink)" stroke-width="3"/><path d="M300 249V324M384 249V324M280 226H405" stroke="var(--ink)" stroke-width="3"/></g><g class="room-props" fill="none" stroke="var(--accent)" stroke-width="2"><path d="M446 329V278M430 293Q415 266 446 274Q472 260 462 293M479 330H512V309H479ZM111 328H209V300H111ZM130 300V277H190V300"/></g><g class="room-flow" fill="none" stroke="var(--accent)" stroke-width="3"><path d="M184 177Q223 248 334 215" pathLength="1"/><path d="M323 207L339 216 326 225"/></g><rect class="blank-area" x="429" y="84" width="105" height="163" rx="4" fill="var(--accent-soft)"/><g class="room-lock" fill="var(--accent)"><circle cx="343" cy="203" r="8"/></g>''','中心 대상과 배경의 관계, 시선 흐름과 창작 여백을 구분한 방의 도식'.replace('中心','중심'),'room')

def reflection():
 return wrap('''<path d="M337 40H588V359H337Z" fill="var(--bone)" stroke="var(--line)" stroke-width="2"/><path d="M462 40V359M337 198H588" stroke="var(--line)"/><g class="face-real" fill="none" stroke="var(--ink)" stroke-width="4" stroke-linecap="round"><circle cx="220" cy="164" r="51"/><path d="M152 314Q151 226 220 223Q289 226 288 314ZM200 160H204M236 160H240M202 185Q220 196 238 185"/></g><g class="face-reflected" fill="none" stroke="var(--accent)" stroke-width="3" stroke-linecap="round"><circle cx="458" cy="164" r="51"/><path d="M390 314Q389 226 458 223Q527 226 526 314ZM438 160H442M474 160H478"/><path class="reflection-mouth" d="M440 190Q458 181 476 190"/></g><path class="reflection-link" d="M274 164H403" stroke="var(--line)" stroke-width="2" stroke-dasharray="5 7"/>''','인물의 실제 얼굴과 창문에 비친 다른 표정의 개념도','portrait')

def diagram(kind):
 return {'hero':glasses,'glasses':glasses,'chain':glasses,'negative':glasses,'patch':glasses,'shop':shop,'street':street,'compare':street,'identity':room,'blank':room,'composition':room,'reflection':reflection}.get(kind,lambda:'')()
